draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw orange
  ctx.fillStyle = '#ffa07a';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // draw peel
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // draw peeling effect
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 * Math.cos(t), H/2 + 50 * Math.sin(t));
  ctx.lineTo(W/2 + 70 * Math.cos(t), H/2 + 70 * Math.sin(t));
  ctx.stroke();

  // draw vitamin C spray
  ctx.fillStyle = '#ff8c00';
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.cos(3*t), H/2 + 100 * Math.sin(3*t), 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
